window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1317f63ad18298c5"]={"versions": [{"id": "FIG-1317f63ad18298c5", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architektur-Übersicht).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentation des AUTOSAR Adaptive Platform (AP) Clusters <em>Platform Health Management</em> (PHM) innerhalb der Cluster-Kategorie <strong>Safety</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Kapitel 9, Release R22-11).</li>\n<li><strong>Technischer Zweck:</strong> Das Diagramm deklariert die funktionale Zuordnung und die Implementierungsstrategie des PHM. PHM fungiert als zentrale Instanz für funktionale Sicherheit auf der AP-Laufzeitumgebung und realisiert die Überwachung von Applikationen (Alive-, Deadline- und Logical Supervision sowie Health Channel Monitoring) mit Anbindung an das Execution Management zur Ausführung von Recovery-Aktionen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entität:</strong></li>\n<li><code>«aapFunctionalCluster» Platform Health Management</code>: Repräsentiert das funktionale Cluster der Adaptive Plattform mit dem Stereotypen <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Eigenschaft / Architektur-Merkmal:</strong></li>\n<li><code>daemon-based</code>: Kennzeichnung der Bereitstellungsform als eigenständiger Betriebssystem-Prozess (Daemon / Service-Prozess) im User Space des POSIX-Betriebssystems im Gegensatz zu rein bibliotheksbasierten Clustern (<code>library-based</code>).</li>\n<li><strong>Beziehungen & Schnittstellen (kontextuell abgeleitet):</strong></li>\n<li><strong>In-Process-Bibliothek (<code>ara::phm</code>):</strong> Client-Bibliothek, die in die überwachten adaptiven Prozesse gelinkt wird.</li>\n<li><strong>Inter-Process-Communication (IPC):</strong> Asynchrone/synchrone Meldepfade zwischen <code>ara::phm</code>-Clients und dem zentralen PHM-Daemon.</li>\n<li><strong>Plattformschnittstelle zu <code>ara::exec</code>:</strong> Schnittstelle zum Execution Management (EM) zur Auslösung deterministischer Sicherheitsreaktionen (z. B. Prozess-Neustart, Zustandswechsel von Function Groups oder Plattform-Reset).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein rein statisches Komponentenschaubild handelt, sind keine Sequenzen dargestellt. Das resultierende Laufzeitverhalten des Daemons gliedert sich normativ wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start des PHM-Daemons durch das Execution Management (EM) in einer definierten Startphase/Function Group.</li>\n<li><strong>Supervision-Zyklus:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Checkpoint-Meldungen (<code>ReportCheckpoint()</code>) von Client-Applikationen über IPC; Verifikation gegen konfigurierte Min/Max-Intervalle.</li>\n<li><strong>Deadline Supervision:</strong> Messung der Latenz zwischen zwei definierten Checkpoints innerhalb eines Prozesses.</li>\n<li><strong>Logical Supervision:</strong> Validierung der Transitionen eines Zustandsgraphen (Transition-Topologie) gegen fehlerhafte Ausführungspfade.</li>\n<li><strong>Health Channel Supervision:</strong> Entgegennahme von expliziten Fehlermeldungen/Zuständen aus Applikationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery Action Pipeline:</strong> Bei Überschreitung von Fehlertoleranzen oder Grenzwerten triggert der Daemon über das Execution Management koordinierte Recovery-Strategien (Process Restart, Function Group Transition, Safe State).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prozess- und Ressourcen-Budgetierung:</strong> Da PHM <code>daemon-based</code> ausgeführt wird, muss der POSIX-OS-Integrator einen eigenen Prozess inklusive Scheduling-Priorität (Echtzeitklasse / FIFO / Round Robin), Stack-/Heap-Budgets und IPC-Endpunkten (Domain Sockets, Shared Memory, Message Queues) vorsehen.</li>\n<li><strong>IPC-Latenz & Deadline-Design:</strong> Aufrufe an <code>ara::phm</code> aus Applikations-Threads dürfen Echtzeitanforderungen nicht verletzen. Die IPC-Kommunikation zum PHM-Daemon muss deterministisch und nicht-blockierend ausgelegt sein, um Verfälschungen bei Deadline Supervisions zu verhindern.</li>\n<li><strong>Safety-Level & ASIL-Dekomposition:</strong> Der PHM-Daemon läuft typischerweise auf dem höchsten geforderten ASIL der überwachten Anwendungen (bis zu ASIL D) und erfordert strenge Speichertrennung (Memory Protection über MMU/MPU) gegenüber ASIL-QM- und niedriger eingestuften Prozessen.</li>\n<li><strong>Konfigurationsartefakte (ARXML):</strong> Entwickler müssen Überwachungsentitäten (<code>SupervisedEntity</code>, <code>Checkpoint</code>, <code>AliveSupervision</code>, <code>DeadlineSupervision</code>, <code>LogicalSupervision</code>) und Recovery-Regeln (<code>RecoveryActionWorkItem</code>, <code>PhmRecoveryActionInterface</code>) im AUTOSAR-Manifest modellieren. Der PHM-Daemon wird zur Generierungs-/Build-Zeit vollständig auf Basis dieser Manifeste konfiguriert.</li>\n</ul>"}, {"id": "FIG-7e6063ba90fba661", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architektur-Übersicht).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentation des AUTOSAR Adaptive Platform (AP) Clusters <em>Platform Health Management</em> (PHM) innerhalb der Cluster-Kategorie <strong>Safety</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Kapitel 9, Release R22-11).</li>\n<li><strong>Technischer Zweck:</strong> Das Diagramm deklariert die funktionale Zuordnung und die Implementierungsstrategie des PHM. PHM fungiert als zentrale Instanz für funktionale Sicherheit auf der AP-Laufzeitumgebung und realisiert die Überwachung von Applikationen (Alive-, Deadline- und Logical Supervision sowie Health Channel Monitoring) mit Anbindung an das Execution Management zur Ausführung von Recovery-Aktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entität:</strong></li>\n<li><code>«aapFunctionalCluster» Platform Health Management</code>: Repräsentiert das funktionale Cluster der Adaptive Plattform mit dem Stereotypen <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Eigenschaft / Architektur-Merkmal:</strong></li>\n<li><code>daemon-based</code>: Kennzeichnung der Bereitstellungsform als eigenständiger Betriebssystem-Prozess (Daemon / Service-Prozess) im User Space des POSIX-Betriebssystems im Gegensatz zu rein bibliotheksbasierten Clustern (<code>library-based</code>).</li>\n<li><strong>Beziehungen & Schnittstellen (kontextuell abgeleitet):</strong></li>\n<li><strong>In-Process-Bibliothek (<code>ara::phm</code>):</strong> Client-Bibliothek, die in die überwachten adaptiven Prozesse gelinkt wird.</li>\n<li><strong>Inter-Process-Communication (IPC):</strong> Asynchrone/synchrone Meldepfade zwischen <code>ara::phm</code>-Clients und dem zentralen PHM-Daemon.</li>\n<li><strong>Plattformschnittstelle zu <code>ara::exec</code>:</strong> Schnittstelle zum Execution Management (EM) zur Auslösung deterministischer Sicherheitsreaktionen (z. B. Prozess-Neustart, Zustandswechsel von Function Groups oder Plattform-Reset).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein rein statisches Komponentenschaubild handelt, sind keine Sequenzen dargestellt. Das resultierende Laufzeitverhalten des Daemons gliedert sich normativ wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start des PHM-Daemons durch das Execution Management (EM) in einer definierten Startphase/Function Group.</li>\n<li><strong>Supervision-Zyklus:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Checkpoint-Meldungen (<code>ReportCheckpoint()</code>) von Client-Applikationen über IPC; Verifikation gegen konfigurierte Min/Max-Intervalle.</li>\n<li><strong>Deadline Supervision:</strong> Messung der Latenz zwischen zwei definierten Checkpoints innerhalb eines Prozesses.</li>\n<li><strong>Logical Supervision:</strong> Validierung der Transitionen eines Zustandsgraphen (Transition-Topologie) gegen fehlerhafte Ausführungspfade.</li>\n<li><strong>Health Channel Supervision:</strong> Entgegennahme von expliziten Fehlermeldungen/Zuständen aus Applikationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery Action Pipeline:</strong> Bei Überschreitung von Fehlertoleranzen oder Grenzwerten triggert der Daemon über das Execution Management koordinierte Recovery-Strategien (Process Restart, Function Group Transition, Safe State).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prozess- und Ressourcen-Budgetierung:</strong> Da PHM <code>daemon-based</code> ausgeführt wird, muss der POSIX-OS-Integrator einen eigenen Prozess inklusive Scheduling-Priorität (Echtzeitklasse / FIFO / Round Robin), Stack-/Heap-Budgets und IPC-Endpunkten (Domain Sockets, Shared Memory, Message Queues) vorsehen.</li>\n<li><strong>IPC-Latenz & Deadline-Design:</strong> Aufrufe an <code>ara::phm</code> aus Applikations-Threads dürfen Echtzeitanforderungen nicht verletzen. Die IPC-Kommunikation zum PHM-Daemon muss deterministisch und nicht-blockierend ausgelegt sein, um Verfälschungen bei Deadline Supervisions zu verhindern.</li>\n<li><strong>Safety-Level & ASIL-Dekomposition:</strong> Der PHM-Daemon läuft typischerweise auf dem höchsten geforderten ASIL der überwachten Anwendungen (bis zu ASIL D) und erfordert strenge Speichertrennung (Memory Protection über MMU/MPU) gegenüber ASIL-QM- und niedriger eingestuften Prozessen.</li>\n<li><strong>Konfigurationsartefakte (ARXML):</strong> Entwickler müssen Überwachungsentitäten (<code>SupervisedEntity</code>, <code>Checkpoint</code>, <code>AliveSupervision</code>, <code>DeadlineSupervision</code>, <code>LogicalSupervision</code>) und Recovery-Regeln (<code>RecoveryActionWorkItem</code>, <code>PhmRecoveryActionInterface</code>) im AUTOSAR-Manifest modellieren. Der PHM-Daemon wird zur Generierungs-/Build-Zeit vollständig auf Basis dieser Manifeste konfiguriert.</li>\n</ul>"}, {"id": "FIG-3f84ffb548797cd3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architektur-Übersicht).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentation des AUTOSAR Adaptive Platform (AP) Clusters <em>Platform Health Management</em> (PHM) innerhalb der Cluster-Kategorie <strong>Safety</strong> gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Kapitel 9, Release R22-11).</li>\n<li><strong>Technischer Zweck:</strong> Das Diagramm deklariert die funktionale Zuordnung und die Implementierungsstrategie des PHM. PHM fungiert als zentrale Instanz für funktionale Sicherheit auf der AP-Laufzeitumgebung und realisiert die Überwachung von Applikationen (Alive-, Deadline- und Logical Supervision sowie Health Channel Monitoring) mit Anbindung an das Execution Management zur Ausführung von Recovery-Aktionen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entität:</strong></li>\n<li><code>«aapFunctionalCluster» Platform Health Management</code>: Repräsentiert das funktionale Cluster der Adaptive Plattform mit dem Stereotypen <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Eigenschaft / Architektur-Merkmal:</strong></li>\n<li><code>daemon-based</code>: Kennzeichnung der Bereitstellungsform als eigenständiger Betriebssystem-Prozess (Daemon / Service-Prozess) im User Space des POSIX-Betriebssystems im Gegensatz zu rein bibliotheksbasierten Clustern (<code>library-based</code>).</li>\n<li><strong>Beziehungen & Schnittstellen (kontextuell abgeleitet):</strong></li>\n<li><strong>In-Process-Bibliothek (<code>ara::phm</code>):</strong> Client-Bibliothek, die in die überwachten adaptiven Prozesse gelinkt wird.</li>\n<li><strong>Inter-Process-Communication (IPC):</strong> Asynchrone/synchrone Meldepfade zwischen <code>ara::phm</code>-Clients und dem zentralen PHM-Daemon.</li>\n<li><strong>Plattformschnittstelle zu <code>ara::exec</code>:</strong> Schnittstelle zum Execution Management (EM) zur Auslösung deterministischer Sicherheitsreaktionen (z. B. Prozess-Neustart, Zustandswechsel von Function Groups oder Plattform-Reset).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein rein statisches Komponentenschaubild handelt, sind keine Sequenzen dargestellt. Das resultierende Laufzeitverhalten des Daemons gliedert sich normativ wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Start des PHM-Daemons durch das Execution Management (EM) in einer definierten Startphase/Function Group.</li>\n<li><strong>Supervision-Zyklus:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Checkpoint-Meldungen (<code>ReportCheckpoint()</code>) von Client-Applikationen über IPC; Verifikation gegen konfigurierte Min/Max-Intervalle.</li>\n<li><strong>Deadline Supervision:</strong> Messung der Latenz zwischen zwei definierten Checkpoints innerhalb eines Prozesses.</li>\n<li><strong>Logical Supervision:</strong> Validierung der Transitionen eines Zustandsgraphen (Transition-Topologie) gegen fehlerhafte Ausführungspfade.</li>\n<li><strong>Health Channel Supervision:</strong> Entgegennahme von expliziten Fehlermeldungen/Zuständen aus Applikationen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery Action Pipeline:</strong> Bei Überschreitung von Fehlertoleranzen oder Grenzwerten triggert der Daemon über das Execution Management koordinierte Recovery-Strategien (Process Restart, Function Group Transition, Safe State).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prozess- und Ressourcen-Budgetierung:</strong> Da PHM <code>daemon-based</code> ausgeführt wird, muss der POSIX-OS-Integrator einen eigenen Prozess inklusive Scheduling-Priorität (Echtzeitklasse / FIFO / Round Robin), Stack-/Heap-Budgets und IPC-Endpunkten (Domain Sockets, Shared Memory, Message Queues) vorsehen.</li>\n<li><strong>IPC-Latenz & Deadline-Design:</strong> Aufrufe an <code>ara::phm</code> aus Applikations-Threads dürfen Echtzeitanforderungen nicht verletzen. Die IPC-Kommunikation zum PHM-Daemon muss deterministisch und nicht-blockierend ausgelegt sein, um Verfälschungen bei Deadline Supervisions zu verhindern.</li>\n<li><strong>Safety-Level & ASIL-Dekomposition:</strong> Der PHM-Daemon läuft typischerweise auf dem höchsten geforderten ASIL der überwachten Anwendungen (bis zu ASIL D) und erfordert strenge Speichertrennung (Memory Protection über MMU/MPU) gegenüber ASIL-QM- und niedriger eingestuften Prozessen.</li>\n<li><strong>Konfigurationsartefakte (ARXML):</strong> Entwickler müssen Überwachungsentitäten (<code>SupervisedEntity</code>, <code>Checkpoint</code>, <code>AliveSupervision</code>, <code>DeadlineSupervision</code>, <code>LogicalSupervision</code>) und Recovery-Regeln (<code>RecoveryActionWorkItem</code>, <code>PhmRecoveryActionInterface</code>) im AUTOSAR-Manifest modellieren. Der PHM-Daemon wird zur Generierungs-/Build-Zeit vollständig auf Basis dieser Manifeste konfiguriert.</li>\n</ul>"}, {"id": "FIG-d0028bd5aae93584", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Komponentendiagramm (Strukturdiagramm / Architektur-Übersicht).</li>\n<li><strong>Architektur-Kontext:</strong> Übersicht der Functional Cluster der AUTOSAR Adaptive Platform (AP) innerhalb der Cluster-Kategorie <strong>Safety</strong> gemäß <code>AUTOSAR_AP_EXP_SWArchitecture</code> (Release R25-11).</li>\n<li><strong>Technischer Zweck:</strong> Das Diagramm deklariert die funktionale Zuordnung und Bereitstellungsform der sicherheitsrelevanten Cluster der Adaptive Plattform: <em>Platform Health Management</em> (PHM) zur anwendungs- und plattformweiten Zustands- und Laufzeitüberwachung sowie <em>Safe Hardware Acceleration</em> (SHA/SHWA) zur standardisierten, funktional sicheren Anbindung und Nutzung von Hardware-Beschleunigern (z. B. GPUs, NPUs, FPGAs) für sicherheitskritische Workloads.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Komponenten:</strong></li>\n<li><code>«aapFunctionalCluster» Platform Health Management</code>: Funktionales Cluster für die funktionale Sicherheit und Plattformüberwachung, deklariert mit dem Stereotypen <code>«aapFunctionalCluster»</code>.</li>\n<li><code>«aapFunctionalCluster» Safe Hardware Acceleration</code>: Neu hinzugefügtes funktionales Cluster der Kategorie Safety zur sicherheitsgerichteten Abstraktion und Steuerung von Hardwarebeschleunigern (<code>ara::shwa</code>).</li>\n<li><strong>Eigenschaften & Bereitstellungsformen:</strong></li>\n<li><code>daemon-based</code> (bei <em>Platform Health Management</em>): Ausführung als eigenständiger Betriebssystemprozess (Daemon) im POSIX-User-Space.</li>\n<li><em>Safe Hardware Acceleration</em> (kein <code>daemon-based</code>-Zusatz): Bereitstellung über Bibliotheken (<code>library-based</code> / <code>ara::shwa</code>) zur direkten Integration in Anwendungskontexte mit hardwarenaher Treiberanbindung.</li>\n<li><strong>Schnittstellen & Interaktionen (kontextuell abgeleitet):</strong></li>\n<li><code>ara::phm</code>: Client-Bibliothek und IPC-Kommunikation zum PHM-Daemon für Alive-, Deadline-, Logical- und Health-Channel-Supervision.</li>\n<li><code>ara::shwa</code>: Standardisierte C++-API für Hardware Acceleration zur Verwaltung von Beschleuniger-Kontexten, Memory-Buffern und deterministischen Ausführungs-Pipelines.</li>\n<li>Plattforminteraktion: Anbindung von PHM an <code>ara::exec</code> (Recovery Actions) sowie funktionale Überwachung von Beschleuniger-Workloads und Driver-Statusmeldungen im Sicherheitskontext.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein rein statisches Komponentenschaubild handelt, sind keine Sequenzen dargestellt. Das resultierende Laufzeitverhalten der Safety-Cluster gliedert sich normativ wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Lifecycle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Start des PHM-Daemons durch das Execution Management (<code>ara::exec</code>) in einer definierten Funktionsgruppe.</li>\n<li>Instanziierung und Konfiguration des Beschleuniger-Treibers und der <code>ara::shwa</code>-Kontexte für berechtigte Adaptive Applications.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeitüberwachung (PHM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Alive Supervision:</strong> Zyklische Checkpoint-Meldungen (<code>ReportCheckpoint()</code>) über IPC zur Überwachung der Ausführungsfrequenz.</li>\n<li><strong>Deadline Supervision:</strong> Messung von Latenzen zwischen Checkpoints (z. B. auch für asynchrone Berechnungszyklen).</li>\n<li><strong>Logical Supervision:</strong> Validierung korrekter Kontrollfluss-Transitionen.</li>\n<li><strong>Health Channel Supervision:</strong> Entgegennahme von Fehlermeldungen und Status-Events aus Applikationen und Hardware-Treibern.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Sichere Hardware-Beschleunigung (Safe Hardware Acceleration):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Anforderung von isolierten Speicher- und Rechenressourcen über <code>ara::shwa</code>.</li>\n<li>Asynchrone Übergabe von Ausführungs-Jobs an Hardware-Beschleuniger und Überwachung der Rückmeldezeiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Recovery- und Fehlermanagement:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Überschreiten von Supervision-Limits oder Treiber-Fehlern triggert PHM über das Execution Management koordinierte Reaktionen (Prozessneustart, Zustandswechsel in einen sicheren Zustand / Safe State).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Prozess- und Ressourcen-Budgetierung (PHM):</strong> Da PHM <code>daemon-based</code> implementiert ist, erfordert es einen eigenen Betriebssystem-Prozess mit Echtzeit-Scheduling-Priorität, dedizierten Stack-/Heap-Budgets und zuverlässigen IPC-Kanälen.</li>\n<li><strong>IPC-Latenz & Deadline-Design:</strong> Aufrufe an <code>ara::phm</code> aus Applikations-Threads dürfen Echtzeitanforderungen nicht verletzen; die IPC-Kommunikation zum Daemon muss deterministisch ausgelegt sein.</li>\n<li><strong>Hardware-Isolation & Freedom from Interference (Safe Hardware Acceleration):</strong> Für Safe Hardware Acceleration müssen Plattform- und Treiber-Entwickler hardwareseitige Speichertrennung (IOMMU/SMMU) sowie deterministische Zugriffsrechte sicherstellen, um Rückwirkungsfreiheit zwischen unterschiedlichen ASIL-Einstufungen zu garantieren.</li>\n<li><strong>API-Konformität:</strong> Applikationen dürfen nicht direkt über ungesicherte OS-Treiber-Bypässe auf Beschleuniger-Hardware zugreifen, sondern müssen die standardisierten <code>ara::shwa</code>-Schnittstellen nutzen, um Safety-Zertifizierbarkeit zu gewährleisten.</li>\n</ul>"}], "trans": [{"from": "FIG-1317f63ad18298c5", "to": "FIG-7e6063ba90fba661", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7e6063ba90fba661", "to": "FIG-3f84ffb548797cd3", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3f84ffb548797cd3", "to": "FIG-d0028bd5aae93584", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>«aapFunctionalCluster» Safe Hardware Acceleration: Neues funktionales Cluster in der Cluster-Kategorie Safety ergänzt.</li>\n</ul>"}]};
